	subroutine SquaredME(result, qext, flags)
	use global_vars
	implicit none
	double precision result(*)
	integer nlegs, flags
        parameter (nlegs = 7)
        double precision qext(nlegs,4)

#include "vars.h"

	double precision sumup
	external sumup

	integer Hel1, Hel2, Hel3, Hel4, Hel5
	integer Hel6, Hel7, Hel8, Hel9
	equivalence (Hel(1), Hel1)
	equivalence (Hel(2), Hel2)
	equivalence (Hel(3), Hel3)
	equivalence (Hel(4), Hel4)
	equivalence (Hel(5), Hel5)
	equivalence (Hel(6), Hel6)
	equivalence (Hel(7), Hel7)
	equivalence (Hel(8), Hel8)
	equivalence (Hel(9), Hel9)

	data MatSUN /1*bogus/

        integer nSUNtree
        parameter (nSUNtree = 1)
        double complex Ctree1(nSUNtree), CtreeVV(nSUNtree), temp
        double complex ampW, ampWm
        double precision SV1, SV2

C the ordering: {MU, MD} -> {MW, MZ, 0} 
	S = SInvariant(1,2)

	T = TInvariant(1,3)

	T14 = TInvariant(1,4)

	U = TInvariant(2,3)

	T24 = TInvariant(2,4)

	S34 = SInvariant(3,4)

c        print*,'from SquaredME:',SInvariant(1,2), SInvariant(6,7), SInvariant(8,9)

C Note: qext(7,4) are the true qq -> 4l + g momenta
	SV1 = qext(3,1)*qext(4,1) - qext(3,2)*qext(4,2) 
     &  - qext(3,3)*qext(4,3) - qext(3,4)*qext(4,4)
        SV1 = SV1*2
	SV2 = qext(5,1)*qext(6,1) - qext(5,2)*qext(6,2) 
     &  - qext(5,3)*qext(6,3) - qext(5,4)*qext(6,4)
        SV2 = SV2*2

	call abbr0_s

	call abbr0_angle

	result(1) = 0
	result(2) = 0

C Warning: helicity order Hel1 (U), Hel2 (Dbar), Hel3 (W+), 
C Hel4 (Z), Hel5 (g), Hel6 (e+), Hel7 (nue), Hel8 (mu+), Hel9 (mu-)
***[sum over quark helicities
       do Hel1 = -1, 1, 2
	Hel2 = -Hel1 !anti-quark 2
       do Hel5 = -1, 1, 2 ! final gluon

	Hel6 = 1 ! final e+
	Hel7 = -1 ! final nue

	Hel8 = -1 ! lepton 3
	Hel9 = -Hel8 ! lepton 4

***[for qq->W+V*Br(W+)*Br(V)
        Ctree1(1) = 0

        do Hel3 = hel_W_min, hel_W_max, hel_W_step ! for V1
        do Hel4 = hel_Z_min, hel_Z_max, hel_Z_step ! for V2

	call abbr0_hel
	Ctree(1) = 0
	call born
        CtreeVV(1) = Ctree(1)

        call decayWll(ampW, 3, 6, 7)
        call decayWmll(ampWm, 4, 8, 9)

c          print*,"hel 5678", Hel5, Hel6, Hel7, Hel8, ampW, ampZ

        temp = -CtreeVV(1)*ampW*ampWm
     &  /((SV1 - CMWsq)*(SV2 - CMWsq))

C Ninh checking
c        temp = -CtreeVV(1)

        Ctree1(1) = Ctree1(1) + temp

        enddo
        enddo
***]for qq->W+V*Br(W+)*Br(V)

	result(1) = result(1) + sumup(Ctree1, Ctree1)

	enddo
	enddo
***]sum over quark helicities
        
#ifdef CHECK
	print *, 'S =', S
	print *, 'T =', T
	print *, 'T14 =', T14
	print *, 'U =', U
	print *, 'T24 =', T24
	print *, 'S34 =', S34

	print *, 'tree =', result(1)
	print *, 'loop =', result(2)
	stop
#endif
	end


************************************************************************

	double precision function sumup(CCloop, CCtree)
	implicit none

#include "vars.h"

	double complex CCloop(1), CCtree(1)
	double complex m

	sumup = 0

	m = 0
	m = m + CCloop(1)*MatSUN(1,1)
	sumup = sumup + DBLE(DCONJG(CCtree(1))*m)
	end
